// === Tab: mySketch ===
let myShader;
let img;
let input;
let shapeSelect;
let outlineCheckbox;
let bwCheckbox; // New checkbox for B&W mode
let particleSlider;
let depthSlider; 
let mode = 3; 

const vert = `#version 300 es
in vec3 aPosition;
void main() {
  gl_Position = vec4(aPosition.xy * 2.0 - 1.0, 0.0, 1.0);
}`;

const frag = `#version 300 es
precision highp float;

uniform vec2 r;
uniform float t;
uniform sampler2D uTex;
uniform int uMode; 
uniform bool uOutline; 
uniform bool uBW; // New uniform for B&W toggle
uniform float uParticleSize;
uniform float uShapeDepth; 
out vec4 o;

float sdBox(vec3 p, vec3 b) {
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float sdCylinder(vec3 p, vec2 h) {
  vec2 d = abs(vec2(length(p.xz),p.y)) - h;
  return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}

float sdHexPrism(vec3 p, vec2 h) {
  const vec3 k = vec3(-0.8660254, 0.5, 0.57735);
  p = abs(p);
  p.xy -= 2.0 * min(dot(k.xy, p.xy), 0.0) * k.xy;
  vec2 d = vec2(
       length(p.xy - vec2(clamp(p.x, -k.z * h.x, k.z * h.x), h.x)) * sign(p.y - h.x),
       p.z - h.y);
  return min(max(d.x, d.y), 0.0) + length(max(d, 0.0));
}

void main() {
  vec3 colorShift = texture(uTex, vec2(0.5)).rgb;
  vec4 FC = gl_FragCoord;
  o = vec4(0.0);
  float minEdgeDist = 100.0;

  for(float i,z,d,s; i++ < 80.0; o += (cos(s + vec4(colorShift, 0.0) * 5.0 + vec4(0,1,2,0)) + 1.) / d * z) {
    vec3 p = z * normalize(FC.xyz * 2. - vec3(r, r.y)),
         a = normalize(cos(vec3(1,2,0) + t - d * 8.));

    p.z += 5.;
    float ry = t * 0.3;
    mat2 m = mat2(cos(ry), -sin(ry), sin(ry), cos(ry));
    p.xz *= m;
    p.xy *= m;

    a = a * dot(a,p) - cross(a,p);
    for(d=1.; d++ < 9.;) {
      a += sin(a * d * uParticleSize + t).yzx / d;
    }

    float shape;
    if(uMode == 0) shape = length(p) - 3.0;        
    else if(uMode == 1) shape = sdBox(p, vec3(2.0, uShapeDepth, 2.0)); 
    else if(uMode == 2) shape = sdCylinder(p, vec2(2.0, uShapeDepth));
    else shape = sdHexPrism(p.xzy, vec2(2.0, uShapeDepth));

    minEdgeDist = min(minEdgeDist, abs(shape));
    z += d = .1 * abs(shape) + .04 * abs(s = a.y);
  }

  o = tanh(o / 3e4);

  // B&W Conversion logic
  if(uBW) {
    float gray = dot(o.rgb, vec3(0.299, 0.587, 0.114));
    o.rgb = vec3(gray);
  }

  float brightness = (o.r + o.g + o.b) / 3.0;
  float edgeMask = smoothstep(0.15, 0.0, minEdgeDist); 

  if(uOutline) {
    o.a = edgeMask * brightness * 2.0;
  } else {
    o.a = clamp(brightness * 2.0, 0.0, 1.0); 
  }
}`;

function setup() {
  setAttributes('alpha', true);
  createCanvas(windowWidth, windowHeight, WEBGL);
  pixelDensity(1); 
  myShader = createShader(vert, frag);

  // Title
  let title = createP('INTENSUM morph generator');
  title.position(10, -10);
  title.style('font-family', 'sans-serif');
  title.style('font-weight', 'bold');
  title.style('font-size', '20px');
  title.style('color', '#000000');

  // UI - File Upload
  input = createFileInput(handleFile);
  input.position(10, 50);

  // UI - Dropdown
  shapeSelect = createSelect();
  shapeSelect.position(10, 80);
  shapeSelect.option('Sphere', 0);
  shapeSelect.option('Box', 1);
  shapeSelect.option('Cylinder', 2);
  shapeSelect.option('Hexagon', 3);
  shapeSelect.selected('3'); 
  shapeSelect.changed(() => { mode = int(shapeSelect.value()); });

  // UI - Outline Checkbox
  outlineCheckbox = createCheckbox(' Show Outline', false);
  outlineCheckbox.position(10, 110);
  outlineCheckbox.style('color', '#000000');

  // UI - B&W Checkbox
  bwCheckbox = createCheckbox(' B&W Mode', false);
  bwCheckbox.position(125, 110); // Placed next to Outline
  bwCheckbox.style('color', '#000000');

  // UI - Particle Size Slider
  particleSlider = createSlider(0.1, 5.0, 1.0, 0.1);
  particleSlider.position(10, 140);
  let pLabel = createSpan('Particle Size');
  pLabel.position(150, 140);
  pLabel.style('color', '#000000');

  // UI - Shape Depth Slider
  depthSlider = createSlider(0.1, 5.0, 2.5, 0.1);
  depthSlider.position(10, 170);
  let dLabel = createSpan('Shape Depth');
  dLabel.position(150, 170);
  dLabel.style('color', '#000000');

  // UI - Save Button
  let saveBtn = createButton('Save PNG');
  saveBtn.position(10, 210);
  saveBtn.mousePressed(saveFractal);

  img = createImage(1, 1);
  img.loadPixels();
  img.set(0, 0, color(255, 100, 0));
  img.updatePixels();
}

function handleFile(file) {
  if (file.type === 'image') img = loadImage(file.data);
}

function saveFractal() {
  saveCanvas('myFractal', 'png');
}

function draw() {
  clear(); 
  shader(myShader);
  myShader.setUniform('r', [width, height]);
  myShader.setUniform('t', millis() / 1000.0);
  myShader.setUniform('uTex', img);
  myShader.setUniform('uMode', mode);
  myShader.setUniform('uOutline', outlineCheckbox.checked());
  myShader.setUniform('uBW', bwCheckbox.checked());
  myShader.setUniform('uParticleSize', particleSlider.value());
  myShader.setUniform('uShapeDepth', depthSlider.value());
  rect(-width/2, -height/2, width, height);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

